 public static void state(VatagState s){var m=Minecraft.getInstance();if(!s.active()){if(s.token().equals(token))clear(false);return;}var nativeCamera=PlatformPilotClient.originalCamera();clear(false);resetCameraRoll();token=s.token();entity=s.entity();original=nativeCamera==null?m.options.getCameraType():nativeCamera;m.options.setCameraType(CameraType.FIRST_PERSON);world=m.level;waiting=0;awaitMonitor=m.player!=null&&!SbwCompat.isMonitor(m.player.getMainHandItem());sequence=0;EXIT_LATCH.reset();mineDeployArmed=false;aim=false;roverView=0;orbitYaw=0;orbitPitch=40;perspectiveHeld=false;yaw=s.yaw();pitch=s.pitch();}
