  var key=com.atsuishio.superbwarfare.init.ModKeyMappings.FIRE.getKey();long handle=m.getWindow().getWindow();
  return key.getType()==com.mojang.blaze3d.platform.InputConstants.Type.MOUSE
   ?org.lwjgl.glfw.GLFW.glfwGetMouseButton(handle,key.getValue())==org.lwjgl.glfw.GLFW.GLFW_PRESS
   :key.getType()==com.mojang.blaze3d.platform.InputConstants.Type.KEYSYM&&key.getValue()>=0&&com.mojang.blaze3d.platform.InputConstants.isKeyDown(handle,key.getValue());
