 public static Vec3 lensPosition(float partial){var v=vehicle();if(v==null)return null;if(v instanceof Sd01Entity sd)return sd.camera(false,partial);var d=(v instanceof Hgd01Entity h?h.cameraFrame(aim,partial):v instanceof Qd01Entity q?q.cameraFrame(aim,partial):v instanceof Wd01Entity w?w.cameraFrame(aim,partial):v.getVehicleTransform(partial)).transformDirection(new org.joml.Vector3d(0,0,1));return v.camera((v instanceof Hgd01Entity||v instanceof Wd01Entity||v instanceof Qd01Entity)&&aim,partial).add(d.x*.06,d.y*.06,d.z*.06);}
 public static float[] lensAngles(float partial){var d=(vehicle() instanceof Sd01Entity sd?sd.cameraFrame(partial):vehicle() instanceof Hgd01Entity h?h.cameraFrame(aim,partial):vehicle() instanceof Qd01Entity q?q.cameraFrame(aim,partial):vehicle() instanceof Wd01Entity w?w.cameraFrame(aim,partial):vehicle().getVehicleTransform(partial)).transformDirection(new org.joml.Vector3d(0,0,1)).normalize();return new float[]{(float)Math.toDegrees(-Math.atan2(d.x,d.z)),(float)-Math.toDegrees(Math.asin(d.y))};}
