 public static int roverView(){return roverView;}
 public static void cycleRoverView(){if(perspectiveHeld)return;perspectiveHeld=true;roverView=(roverView+1)%3;orbitYaw=0;orbitPitch=roverView==2?78:40;var m=Minecraft.getInstance();m.options.setCameraType(CameraType.FIRST_PERSON);if(m.player!=null)m.player.displayClientMessage(net.minecraft.network.chat.Component.literal((vehicle() instanceof Sd01Entity?"SD-01 camera: ":vehicle() instanceof Gad01Entity?"GAD-01 camera: ":vehicle() instanceof Hgd01Entity?"HGD-01 camera: ":vehicle() instanceof Qd01Entity?"QD-01 camera: ":vehicle() instanceof Wd01Entity?"WD-01 camera: ":vehicle() instanceof Dc01Entity?"DC-01 camera: ":vehicle() instanceof MineRoverEntity?"MR-01 camera: ":"SR-01 camera: ")+new String[]{"Lens","Follow","Overhead"}[roverView]),true);}
 public static Vec3 viewPosition(float partial){
  var r=vehicle();if(roverView==0)return lensPosition(partial);var base=r.getVehicleTransform(partial).transformPosition(new org.joml.Vector3d(0,1.1,0));Vec3 target=new Vec3(base.x,base.y,base.z);double distance=r instanceof Sd01Entity?(roverView==2?14:10):r instanceof Hgd01Entity?(roverView==2?16:12):roverView==2?10:6;
  if(r instanceof SupplyRoverEntity sr&&sr.partner()!=null){for(var e:Minecraft.getInstance().level.entitiesForRendering())if(e.getUUID().equals(sr.partner())){target=target.add(e.getPosition(partial).add(0,1,0)).scale(.5);distance=roverView==2?14:9;break;}}
  float y=Mth.rotLerp(partial,r.yRotO,r.getYRot())+orbitYaw;Vec3 direction=Vec3.directionFromRotation(orbitPitch,y);Vec3 desired=target.subtract(direction.scale(distance));return RoverViewCollision.clip(r,target,desired);
 }
