 public static void look(double dx,double dy){if(!active())return;var m=Minecraft.getInstance();double f=m.options.sensitivity().get()*.6+.2;float gain=(float)(f*f*f*8*.15);if(groundCamera()&&roverView!=0){orbitYaw+=(float)dx*gain;orbitPitch=Mth.clamp(orbitPitch+(float)dy*gain,5,89);return;}yaw+=(float)dx*gain;pitch=Mth.clamp(pitch+(float)dy*gain*(m.options.invertYMouse().get()?-1:1),-85,85);}
